'use strict';
const $=id=>document.getElementById(id);
const api=(action,payload={})=>window.tradingAgents.request(action,payload);
const state={page:'analysis',config:{},history:[],roleReports:{},roleStates:{},selectedRole:'Portfolio Manager',report:null,reportId:null,analysisReportId:null,busy:false,action:null,started:0,events:0,llms:0,tools:0,authAttempt:null,modelCatalog:{},executionModels:null,deepseekConfigured:false,routingDraft:null,routingPresets:{}};
const providerNames={codex_cli:'Codex CLI',agy_cli:'Antigravity / agy',deepseek:'DeepSeek API',chatgpt:'ChatGPT Subscription'};
const groups=[
 ['01','Analyst Team',['Market Analyst','Sentiment Analyst','News Analyst','Fundamentals Analyst']],
 ['02','Research Team',['Bull Researcher','Bear Researcher','Research Manager']],
 ['03','Trading Team',['Trader']],
 ['04','Risk Management',['Aggressive Analyst','Conservative Analyst','Neutral Analyst']],
 ['05','Portfolio Management',['Portfolio Manager']],
 ['06','Memory & Reflection',['Memory Log']]
];
function workflowGroups(){return groups;}
const sections={market:'Market Analyst',sentiment:'Sentiment Analyst',news:'News Analyst',fundamentals:'Fundamentals Analyst',bull:'Bull Researcher',bear:'Bear Researcher',manager:'Research Manager',trader:'Trader',aggressive:'Aggressive Analyst',conservative:'Conservative Analyst',neutral:'Neutral Analyst',decision:'Portfolio Manager',memory:'Memory Log'};
const titles={evidence:['Dữ liệu & quyết định','DỮ LIỆU'],paper:['Danh mục tiền ảo','TIỀN ẢO'],analysis:['Phân tích thị trường','PHÂN TÍCH'],reports:['Thư viện báo cáo','BÁO CÁO'],backtest:['Đánh giá chiến lược','BACKTEST'],memory:['Memory & phản tư','MEMORY'],settings:['Mô hình & dữ liệu','CẤU HÌNH']};
function node(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=String(text);return el;}
function notice(message,kind='error'){const box=$('notice');box.textContent=message;box.className='notice '+kind;box.hidden=false;}
function clearNotice(){$('notice').hidden=true;}
function guard(fn){return async(...args)=>{try{await fn(...args);}catch(error){notice(error.message||String(error));}};}
function navigate(page){if(!titles[page])return;if(state.page==='paper'&&page!=='paper')window.PaperMarket?.stop();state.page=page;document.querySelector('main').scrollTop=0;document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!=='page-'+page);document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('selected',x.dataset.page===page));$('page-title').textContent=titles[page][0];$('breadcrumb').textContent=titles[page][1];clearNotice();if(page==='memory')refreshMemory().catch(e=>notice(e.message));if(page==='reports')renderHistory();if(page==='settings'){refreshSubscription().catch(()=>{$('subscription-status').textContent='Chưa xác minh';});refreshDeepSeek().catch(()=>{$('deepseek-key-status').textContent='Chưa xác minh khóa';});}if(page==='evidence')renderEvidence();if(page==='paper')refreshPaper().catch(e=>notice(e.message));}
function renderWorkflow(){if($('metric-reports'))$('metric-reports').textContent='Vai trò có báo cáo: '+Object.keys(state.roleReports).length;const container=$('workflow');container.replaceChildren();for(const [number,title,roles]of workflowGroups()){const group=node('div','team-group');const heading=node('div','team-heading');heading.append(node('span','team-number',number),node('span','',title));group.append(heading);for(const role of roles){const status=state.roleStates[role]||'pending';const incomplete=!(state.busy&&state.action==='analyze')&&!!state.report?.integration?.report_quality?.incomplete_roles?.[role];const button=node('button','role-button '+status+(incomplete?' incomplete':''));button.type='button';const saved=state.analysisReportId&&!(state.busy&&state.action==='analyze');const recorded=saved?state.executionModels?.[role]:null;const assignment=saved?(recorded?{provider:recorded.provider,model:recorded.requested_model}:null):state.config.desktop_role_models?.[role];if(assignment)button.title=(providerNames[assignment.provider]||assignment.provider)+' · '+assignment.model;button.classList.toggle('active',role===state.selectedRole);button.append(node('span','role-dot'),node('span','role-label',role),...(assignment?[node('span','role-provider',assignment.provider==='codex_cli'?'Codex':assignment.provider==='agy_cli'?'agy':assignment.provider==='deepseek'?'DeepSeek':assignment.provider)]:[]),node('span','role-state',incomplete?'Chưa đầy đủ':status==='failed'?'Lỗi':status==='cancelled'?'Đã dừng':(status==='completed'?'Hoàn tất':status==='running'?'Đang chạy':state.busy?'Chờ':state.analysisReportId?'Chưa lưu':'Chưa chạy')));button.onclick=()=>selectRole(role);group.append(button);}container.append(group);}}
function selectRole(role){state.selectedRole=role;renderWorkflow();const report=state.roleReports[role];$('current-role-title').textContent=role;$('current-role-detail').textContent=report?(report.detail||'Báo cáo từ TradingAgents'):(state.busy?'Báo cáo sẽ hiển thị ngay khi vai trò này hoàn thành.':'Chọn báo cáo đã lưu hoặc bắt đầu phân tích mới.');$('current-document').replaceChildren();$('current-document').scrollTop=0;if(report){$('current-document').innerHTML=report.html;}else{const empty=node('div','empty-state');empty.append(node('h2','',state.busy?'Đang chờ kết quả':'Chưa có kết quả cho role này'),node('p','',state.busy?'Bạn có thể đọc các role đã hoàn tất trong lúc phần còn lại tiếp tục.':'Nội dung báo cáo chỉ xuất hiện sau khi TradingAgents tạo kết quả.'));$('current-document').append(empty);}$('current-full-report').disabled=!state.analysisReportId;}
function eventLog(kind,message){const log=$('event-log');if(!state.events)log.replaceChildren();state.events++;const row=node('div','event-row '+kind);row.append(node('time','',new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})));const text=node('div');text.append(node('small','',kind==='warning'?'Nguồn dữ liệu':kind==='error'?'Lỗi':kind==='tool'?'Công cụ':kind==='model'?'Mô hình':'Tiến trình'),node('p','',message));row.append(text);log.append(row);while(log.children.length>300)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;}
function setBusy(busy,action=null){state.busy=busy;state.action=action;for(const field of document.querySelectorAll('#analysis-form input,#analysis-form select,#analysis-form textarea,#backtest-form input,#backtest-form select,#backtest-form textarea'))field.disabled=busy;for(const id of ['preset-cli','preset-codex-deepseek','preset-three','preset-inherit'])$(id).disabled=busy;if(!busy){document.querySelector('#analysis-form input[value=fundamentals]').disabled=$('asset-type').value==='crypto';document.querySelector('.bt-analysts input[value=fundamentals]').disabled=$('bt-asset').value==='crypto';$('html-report-flag').disabled=!$('save-report-flag').checked;}$('run-button').disabled=busy;$('backtest-button').disabled=busy;$('settle-button').disabled=busy;$('settle-all-button').disabled=busy;$('save-settings').disabled=busy;$('save-json').disabled=busy;$('clear-checkpoints').disabled=busy;$('save-routing').disabled=busy;$('save-deepseek-key').disabled=busy;$('test-deepseek').disabled=busy;$('remove-deepseek-key').disabled=busy;$('use-codex').disabled=busy;$('use-agy').disabled=busy;$('use-deepseek').disabled=busy;$('subscription-login').disabled=busy;$('subscription-use').disabled=busy;$('subscription-logout').disabled=busy;$('cancel-button').hidden=!busy;$('bt-cancel').hidden=!(busy&&action==='backtest');if($('subscription-cancel'))$('subscription-cancel').hidden=!(busy&&action==='subscription_login');$('run-badge').textContent=busy?'Đang chạy':'Sẵn sàng';$('run-badge').className='badge'+(busy?' running':'');$('top-status').textContent=busy?(action==='backtest'?'Backtest đang chạy':action==='subscription_login'?'Đang đăng nhập ChatGPT':'TradingAgents đang nghiên cứu'):'Không gian nghiên cứu TradingAgents';}
function portfolio(){const text=$('portfolio').value.trim();return text?JSON.parse(text):null;}
function analysisPayload(){const chosen=[...document.querySelectorAll('#analysis-form .analyst-options input:checked')].filter(x=>!x.disabled).map(x=>x.value);if(!chosen.length)throw new Error('Chọn ít nhất một analyst.');return {ticker:$('ticker').value.trim(),date:$('trade-date').value,asset_type:$('asset-type').value,analysts:chosen,portfolio:portfolio(),save:$('save-report-flag').checked,html:$('html-report-flag').checked,show:$('show-report-flag').checked};}
async function launch(action,payload){clearNotice();if(state.busy)throw new Error('Một tác vụ đang chạy.');state.started=Date.now();state.llms=0;state.tools=0;setBusy(true,action);try{await api('start',{action,payload});}catch(error){setBusy(false);throw error;}}
async function startAnalysis(event){event?.preventDefault();const payload=analysisPayload();state.roleReports={};state.roleStates={};state.report=null;state.reportId=null;state.analysisReportId=null;state.selectedRole='Market Analyst';renderWorkflow();selectRole(state.selectedRole);$('flow-caption').textContent=payload.ticker+' · '+payload.date;await launch('analyze',payload);selectRole(state.selectedRole);eventLog('progress','Bắt đầu phân tích '+payload.ticker+' — '+payload.date);}
function updateConfigUI(){state.routingDraft=null;const cfg=state.config;$('cfg-provider').value=cfg.llm_provider||'codex_cli';$('cfg-language').value=cfg.output_language||'Vietnamese';$('cfg-quick-provider').value=cfg.quick_think_provider||'';$('cfg-deep-provider').value=cfg.deep_think_provider||'';$('cfg-quick-model').value=cfg.quick_think_llm||'';$('cfg-deep-model').value=cfg.deep_think_llm||'';$('cfg-debate').value=cfg.max_debate_rounds;$('cfg-risk').value=cfg.max_risk_discuss_rounds;$('cfg-checkpoint').checked=!!cfg.checkpoint_enabled;$('config-json').value=JSON.stringify(cfg,null,2);$('quick-summary').textContent=(cfg.quick_think_provider||cfg.llm_provider)+' / '+cfg.quick_think_llm;$('deep-summary').textContent=(cfg.deep_think_provider||cfg.llm_provider)+' / '+cfg.deep_think_llm;$('checkpoint-summary').textContent=cfg.checkpoint_enabled?'Bật':'Tắt';$('provider-note').textContent=cfg.llm_provider==='chatgpt'?'ChatGPT Subscription':cfg.llm_provider==='codex_cli'?'Codex CLI':cfg.llm_provider==='agy_cli'?'agy CLI':cfg.llm_provider;const labels={core_stock_apis:'Giá & khối lượng',technical_indicators:'Chỉ báo kỹ thuật',fundamental_data:'Dữ liệu cơ bản',news_data:'Tin tức',macro_data:'Vĩ mô',prediction_markets:'Thị trường dự đoán'};const fields=$('vendor-fields');fields.replaceChildren();for(const [key,value]of Object.entries(cfg.data_vendors||{})){const label=node('label','',labels[key]||key);const input=node('input');input.dataset.vendor=key;input.value=value;label.append(input);fields.append(label);}renderRouting();$('cfg-vietnam').checked=!!cfg.desktop_vietnam?.enabled;$('cfg-paper').checked=!!cfg.desktop_vietnam?.paper_enabled;$('cfg-usage').checked=!!cfg.desktop_usage?.enabled;$('cfg-paid-budget').checked=!!cfg.desktop_budget?.enabled;$('cfg-paid-requests').value=cfg.desktop_budget?.deepseek_max_requests??1;$('cfg-paid-output').value=cfg.desktop_budget?.deepseek_max_output_tokens??1024;$('cfg-paid-backtest').checked=!!cfg.desktop_budget?.deepseek_in_backtest;const counts={};for(const spec of Object.values(cfg.desktop_role_models||{}))counts[spec.provider]=(counts[spec.provider]||0)+1;$('routing-budget-summary').textContent='Lượt chạy kế tiếp: Codex '+(counts.codex_cli||0)+' · Antigravity '+(counts.agy_cli||0)+' · DeepSeek '+(counts.deepseek||0)+(cfg.desktop_budget?.enabled?' · giới hạn '+cfg.desktop_budget.deepseek_max_requests+' request DeepSeek, '+cfg.desktop_budget.deepseek_max_output_tokens+' output token/request.':'');}
async function saveSettings(){const cfg=structuredClone(state.config);Object.assign(cfg,{llm_provider:$('cfg-provider').value.trim(),output_language:$('cfg-language').value.trim(),quick_think_provider:$('cfg-quick-provider').value.trim()||null,deep_think_provider:$('cfg-deep-provider').value.trim()||null,quick_think_llm:$('cfg-quick-model').value.trim(),deep_think_llm:$('cfg-deep-model').value.trim(),max_debate_rounds:Number($('cfg-debate').value),max_risk_discuss_rounds:Number($('cfg-risk').value),checkpoint_enabled:$('cfg-checkpoint').checked,desktop_role_models:readRouting(),desktop_vietnam:{enabled:$('cfg-vietnam').checked,paper_enabled:$('cfg-paper').checked},desktop_usage:{enabled:$('cfg-usage').checked,cache_enabled:$('cfg-usage').checked},desktop_budget:{enabled:$('cfg-paid-budget').checked,deepseek_max_requests:Number($('cfg-paid-requests').value),deepseek_max_output_tokens:Number($('cfg-paid-output').value),deepseek_in_backtest:$('cfg-paid-backtest').checked}});document.querySelectorAll('[data-vendor]').forEach(x=>cfg.data_vendors[x.dataset.vendor]=x.value.trim());state.config=await api('save_config',{config:cfg});updateConfigUI();notice('Đã lưu cấu hình. Lượt chạy tiếp theo sẽ dùng các thiết lập này.','success');}
async function doctor(){const button=$('doctor-button');button.disabled=true;$('health-label').textContent='Đang kiểm tra…';try{const result=await api('doctor');$('doctor-output').textContent=JSON.stringify(result,null,2);$('health-label').textContent=result.status==='pass'?'Cài đặt hợp lệ':'Cần kiểm tra cấu hình';$('health-dot').className='status-dot '+(result.status==='pass'?'ok':'error');}catch(error){$('health-label').textContent='Kiểm tra cấu hình';$('health-dot').className='status-dot error';$('doctor-output').textContent=error.message;notice(error.message);}finally{button.disabled=false;}}
async function refreshHistory(){state.history=await api('history');$('report-count').textContent=state.history.length;renderHistory();const latest=state.history[0];$('latest-open').disabled=!latest;if(latest){$('latest-title').textContent=latest.ticker+' · '+latest.rating;$('latest-detail').textContent=latest.date+' · Báo cáo TradingAgents đã lưu';$('latest-open').onclick=guard(()=>openReport(latest.id,true));}return state.history;}
function renderHistory(){const list=$('report-list');list.replaceChildren();const query=$('report-search').value.toLowerCase();const items=state.history.filter(x=>(x.ticker+' '+x.date+' '+x.rating).toLowerCase().includes(query));for(const item of items){const button=node('button','report-item'+(state.reportId===item.id?' selected':''));const name=node('div');name.append(node('strong','',item.ticker),node('small','',item.date+' · '+new Date(item.modified*1000).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})+(item.backtest?' · Backtest':'')));button.append(name,node('span','rating',item.rating));button.onclick=guard(()=>openReport(item.id,true));list.append(button);}if(!items.length)list.append(node('div','empty-state','Chưa có báo cáo phù hợp.'));}
async function loadReport(id){const report=await api('report',{id});state.report=report;state.reportId=id;$('flow-caption').textContent='Đang xem lượt đã lưu · phân công tại thời điểm chạy, không phải cấu hình lượt tiếp theo';if(!(state.busy&&state.action==='analyze')){state.analysisReportId=id;state.executionModels=report.execution?.models||null;state.roleReports={};state.roleStates={};for(const section of report.sections){const role=sections[section.name];if(role){state.roleReports[role]={html:section.html,text:section.text,detail:'Báo cáo đã lưu · '+(state.history.find(x=>x.id===id)?.date||'')};state.roleStates[role]='completed';}}}return report;}

async function openReport(id,goToReports=false){await loadReport(id);renderEvidence();renderWorkflow();selectRole(state.selectedRole);$('current-full-report').disabled=!state.analysisReportId;$('open-report').disabled=false;$('copy-report').disabled=false;const select=$('report-section');select.replaceChildren(new Option('Báo cáo đầy đủ','all'));state.report.sections.forEach((section,index)=>select.add(new Option(sections[section.name]||section.name,String(index))));showReportSection();renderHistory();if(goToReports)navigate('reports');}
function showTransientPreview(preview){state.report=preview;state.reportId=null;const select=$('report-section');select.replaceChildren(new Option('Báo cáo đầy đủ — xem tạm','all'));preview.sections.forEach((section,index)=>select.add(new Option(sections[section.name]||section.name,String(index))));$('open-report').disabled=true;$('copy-report').disabled=true;showReportSection();navigate('reports');}
function showReportSection(){const choice=$('report-section').value;$('report-empty').hidden=true;$('report-frame').hidden=true;$('section-text').hidden=false;$('section-text').scrollTop=0;$('section-text').innerHTML=choice==='all'?state.report.rendered:state.report.sections[Number(choice)].html;}
async function refreshMemory(){const data=await api('memory');const entries=data.entries||[];const pending=entries.filter(x=>x.pending).length;const stats=$('memory-stats');stats.replaceChildren();for(const [number,label]of [[entries.length,'Quyết định đã lưu'],[pending,'Chờ settlement'],[entries.length-pending,'Đã có kết quả']]){const item=node('div','stat');item.append(node('strong','',number),node('span','',label));stats.append(item);}const body=$('memory-body');body.replaceChildren();for(const entry of entries.slice().reverse()){const row=node('tr');for(const value of [entry.ticker,entry.date,entry.rating,entry.pending?'Chờ kết quả':'Đã giải quyết',entry.reflection||entry.decision||entry.raw||'—']){const cell=node('td');if(String(value).length>360){const details=node('details');details.append(node('summary','','Đọc nhận định / bài học'),node('div','memory-text',value));cell.append(details);}else cell.textContent=String(value);row.append(cell);}body.append(row);}if(!entries.length){const row=node('tr');const td=node('td','','Chưa có quyết định trong memory. Chạy phân tích để bắt đầu ghi nhận.');td.colSpan=5;row.append(td);body.append(row);}}
function formatSummary(result){const parts=['Run ID: '+result.run_id,'Đã chạy: '+result.cells_run+' ô · Đã có từ trước: '+result.skipped];if(result.summary){parts.push('Đã settlement: '+result.summary.resolved+' · Chờ: '+result.summary.pending);for(const [rating,score]of Object.entries(result.summary.by_rating||{}))parts.push(rating+': n='+score.count+', hit rate='+(score.hit_rate===null?'—':(score.hit_rate*100).toFixed(1)+'%')+', mean alpha='+(score.mean_alpha*100).toFixed(2)+'%');}if(result.failures?.length)parts.push('Các ô thất bại:\n'+result.failures.map(x=>x.join(' · ')).join('\n'));if(result.settlement_failures?.length)parts.push('Chưa settlement:\n'+result.settlement_failures.map(x=>x.join(' · ')).join('\n'));return parts.join('\n\n');}
async function refreshSubscription(){const result=await api('subscription_status');$('subscription-status').textContent=result.signed_in?'Đã đăng nhập'+(result.email?' · '+result.email:''):'Chưa đăng nhập';$('subscription-status').className='badge'+(result.signed_in?' running':'');return result;}
async function useSubscription(){const auth=await refreshSubscription();if(!auth.signed_in){notice('Đăng nhập ChatGPT trước khi sử dụng Subscription.');return;}const catalog=await api('subscription_models');const first=catalog.models?.[0]?.id;if(!first)throw new Error('Chưa lấy được model của gói ChatGPT.');const cfg={...state.config,llm_provider:'chatgpt',quick_think_provider:null,deep_think_provider:null,quick_think_llm:first,deep_think_llm:first,temperature:null,max_tokens:null};state.config=await api('save_config',{config:cfg});updateConfigUI();notice('Đã chọn ChatGPT Subscription. Có thể đổi model từng tầng trong cấu hình.','success');}
function defaultModel(provider,tier='quick'){if(provider==='codex_cli')return tier==='deep'?'gpt-6.1-sol':'gpt-6-luna';if(provider==='agy_cli')return 'gemini-3.8-flash-high';if(provider==='deepseek')return 'deepseek-flash';return state.modelCatalog[provider]?.[tier]?.find(x=>x[1]!=='custom')?.[1]||'';}
function renderRouting(){const routes=state.routingDraft===null?(state.config.desktop_role_models||{}):state.routingDraft;const body=$('routing-body');body.replaceChildren();for(const [,team,roles]of groups){for(const role of roles){const spec=routes[role];const row=node('tr');const label=node('td');label.append(node('strong','',role),node('small','',team));const providerCell=node('td');const select=node('select');select.dataset.roleProvider=role;select.setAttribute('aria-label','Nhà cung cấp cho '+role);select.add(new Option('Thừa kế theo tầng',''));for(const [value,name]of Object.entries(providerNames))select.add(new Option(name,value));select.value=spec?.provider||'';const modelCell=node('td');const input=node('input');input.dataset.roleModel=role;input.setAttribute('aria-label','Model cho '+role);input.value=spec?.model||'';input.placeholder='Dùng model mặc định theo tầng';input.disabled=!select.value;select.onchange=()=>{input.disabled=!select.value;input.value=select.value?defaultModel(select.value):'';};providerCell.append(select);modelCell.append(input);const effortCell=node('td');const effort=node('select');effort.dataset.roleEffort=role;effort.setAttribute('aria-label','Reasoning effort cho '+role);for(const v of ['','low','medium','high','xhigh','max'])effort.add(new Option(v||'Mặc định',v));effort.value=spec?.effort||'';effortCell.append(effort);row.append(label,providerCell,modelCell,effortCell);body.append(row);}}}
function readRouting(){const routes={};for(const field of document.querySelectorAll('[data-role-provider]')){if(!field.value)continue;const model=[...document.querySelectorAll('[data-role-model]')].find(x=>x.dataset.roleModel===field.dataset.roleProvider)?.value.trim();if(!model)throw new Error('Chọn model cho '+field.dataset.roleProvider);const previous=(state.routingDraft||state.config.desktop_role_models)?.[field.dataset.roleProvider];const effort=[...document.querySelectorAll('[data-role-effort]')].find(x=>x.dataset.roleEffort===field.dataset.roleProvider)?.value;routes[field.dataset.roleProvider]={provider:field.value,model,...(['codex_cli','deepseek'].includes(field.value)&&effort?{effort}:{}),...(previous?.max_tokens&&previous.provider===field.value?{max_tokens:previous.max_tokens}:{}),...(previous?.backend_url&&previous.provider===field.value?{backend_url:previous.backend_url}:{})};}return routes;}
async function refreshDeepSeek(){const result=await api('api_key_status',{provider:'deepseek'});state.deepseekConfigured=result.configured;$('deepseek-key-status').textContent=result.configured?'Đã lưu khóa trên máy':'Chưa cấu hình khóa';$('deepseek-key-status').className='provider-state '+(result.configured?'connected':'');return result;}
async function useDefaultProvider(provider){if(provider==='deepseek'&&!state.deepseekConfigured)throw new Error('Lưu khóa DeepSeek trước khi sử dụng.');if(provider==='deepseek'&&state.config.desktop_budget?.enabled){const preset=state.routingPresets.balanced_three;if(!preset)throw new Error('Chờ đồng bộ cấu hình mới.');const cfg={...state.config,desktop_role_models:structuredClone(preset.routes),desktop_budget:structuredClone(preset.budget)};state.config=await api('save_config',{config:cfg});updateConfigUI();renderWorkflow();notice('Đã áp dụng Codex 6 · DeepSeek 6 · Antigravity 1.','success');return;}const cfg={...state.config,llm_provider:provider,quick_think_provider:null,deep_think_provider:null,backend_url:null,quick_think_backend_url:null,deep_think_backend_url:null,quick_think_llm:defaultModel(provider),deep_think_llm:defaultModel(provider,'deep'),desktop_role_models:{}};state.config=await api('save_config',{config:cfg});updateConfigUI();notice('Đã chọn '+providerNames[provider]+'.','success');}
function codexRoleSpec(role){const light=['Market Analyst','News Analyst','Fundamentals Analyst','Memory Log'].includes(role);return {provider:'codex_cli',model:light?'gpt-6-luna':'gpt-6.1-sol',effort:role==='Portfolio Manager'?'high':light||['Research Manager','Trader','Conservative Analyst'].includes(role)?'medium':'low'};}
function readPaidBudget(){return {enabled:$('cfg-paid-budget').checked,deepseek_max_requests:Number($('cfg-paid-requests').value),deepseek_max_output_tokens:Number($('cfg-paid-output').value),deepseek_in_backtest:$('cfg-paid-backtest').checked};}
function presetRouting(includeAgy){if(!state.deepseekConfigured){notice('Thêm khóa DeepSeek trước khi dùng mẫu phối hợp.');return;}const preset=state.routingPresets[includeAgy?'balanced_three':'balanced_two'];if(!preset)throw new Error('Chờ đồng bộ cấu hình mới để chọn mẫu.');state.routingDraft=structuredClone(preset.routes);const budget=preset.budget;$('cfg-paid-budget').checked=budget.enabled;$('cfg-paid-requests').value=budget.deepseek_max_requests;$('cfg-paid-output').value=budget.deepseek_max_output_tokens;$('cfg-paid-backtest').checked=budget.deepseek_in_backtest;renderRouting();$('routing-budget-summary').textContent=(includeAgy?'Mẫu đang soạn: Codex 6 · DeepSeek 6 · Antigravity 1':'Mẫu đang soạn: Codex 7 · DeepSeek 6')+' · tối đa '+budget.deepseek_max_requests+' request DeepSeek/lượt, '+budget.deepseek_max_output_tokens+' output token/request. Chưa lưu.';notice('Đã điền mẫu phân công cân bằng. Bấm Lưu phân công để áp dụng cả phân công và giới hạn mới.','success');}
