window.tradingAgents.onEvent(event=>{const data=event.payload||{};switch(event.type){
 case 'node':if(data.name){state.roleStates[data.name]=data.status;renderWorkflow();if(data.status==='running')$('flow-caption').textContent='Đang xử lý: '+data.name;}break;
 case 'role_report':state.roleReports[data.name]={html:data.html,text:data.text,detail:'Kết quả vừa hoàn tất · '+(state.runTicker||$('ticker').value)+' · '+(state.runDate||$('trade-date').value)};state.roleStates[data.name]='completed';renderWorkflow();eventLog('progress',data.name+' đã cập nhật báo cáo');if(state.selectedRole===data.name||!state.roleReports[state.selectedRole])selectRole(data.name);break;
 case 'tool':if(data.status==='running'){state.tools++;if($('metric-tools'))$('metric-tools').textContent='Lượt công cụ: '+state.tools;eventLog('tool',data.name);}break;
 case 'inference':state.llms++;if($('metric-llm'))$('metric-llm').textContent='Lượt LLM: '+state.llms;eventLog('model','Đang suy luận · lượt '+state.llms);break;
 case 'warning':eventLog('warning',data.message);break;
 case 'started':state.runTicker=data.ticker;state.runDate=data.date;eventLog('progress',data.ticker+' · '+data.date);break;
 case 'cell':$('backtest-output').className='backtest-summary';$('backtest-output').textContent='Đang xử lý ô '+data.done+'/'+data.total+'\n'+data.ticker+' · '+data.date;break;
 case 'subscription_pending':state.authAttempt=data.attempt_id;$('subscription-flow').hidden=false;break;
 case 'subscription_url':state.authAttempt=data.attempt_id;$('subscription-url').href=data.url;$('subscription-url').textContent='Mở trang đăng nhập ChatGPT ↗';$('subscription-flow').hidden=false;break;
 case 'subscription_message':eventLog('progress',data.message);break;
 case 'subscription_status':refreshSubscription().catch(()=>{});break;
 case 'completed':{const action=state.action;setBusy(false);$('flow-caption').textContent='Đã hoàn tất tác vụ.';$('run-badge').textContent='Hoàn tất';eventLog('progress','Tác vụ hoàn tất.');if(action==='analyze'){if(data.report_id){refreshHistory().then(()=>openReport(data.report_id,false)).then(()=>selectRole('Portfolio Manager')).then(()=>data.show?navigate('reports'):null).catch(e=>notice(e.message));}else{state.report={integration:data};renderEvidence();selectRole('Portfolio Manager');if(data.show&&data.preview)showTransientPreview(data.preview);notice('Phân tích hoàn tất. Báo cáo role đang có trong phiên này; tùy chọn lưu báo cáo đã tắt.','success');}}else if(action==='backtest'){$('backtest-output').className='backtest-summary';$('backtest-output').textContent=formatSummary(data);$('bt-run-id').value=data.run_id||'';refreshHistory().catch(()=>{});}else if(action==='test_provider'){notice('Đã kết nối '+(providerNames[data.provider]||data.provider)+'.','success');}else if(action==='paper_advance'){refreshPaper().catch(e=>notice(e.message));notice('Đã đối soát tài khoản tiền ảo theo các phiên đã đóng.','success');}else if(action==='settle'){refreshMemory().catch(()=>{});notice('Đã xử lý settlement. '+JSON.stringify(data),'success');}else if(action==='subscription_login'){$('subscription-flow').hidden=true;refreshSubscription().catch(()=>{});notice('Đăng nhập ChatGPT thành công. Bấm “Sử dụng Subscription” để chọn provider.','success');}break;}
 case 'grounding':eventLog('progress','Đã kiểm tra context '+data.role+' · '+data.news_count+' tiêu đề có ID nguồn.');break;
 case 'quantitative':eventLog('progress',data.ticker+' · '+data.available+'/'+(data.applicable_total??data.total)+' chỉ tiêu có số liệu'+(data.not_applicable?' · '+data.not_applicable+' không áp dụng':'')+' · giá phiên '+data.quote_date);break;
 case 'usage':break;
 case 'progress':eventLog('progress',data.message);break;
 case 'failed':for(const role in state.roleStates)if(state.roleStates[role]==='running')state.roleStates[role]='failed';renderWorkflow();if(state.action==='subscription_login'){$('subscription-flow').hidden=true;state.authAttempt=null;}setBusy(false);$('run-badge').textContent='Cần kiểm tra';$('run-badge').className='badge failed';eventLog('error',data.message);notice(data.message);break;
 case 'cancelled':for(const role in state.roleStates)if(state.roleStates[role]==='running')state.roleStates[role]='cancelled';renderWorkflow();if(state.action==='subscription_login'){$('subscription-flow').hidden=true;state.authAttempt=null;$('subscription-url').href='#';}setBusy(false);$('run-badge').textContent='Đã dừng';eventLog('progress',data.message);notice(data.message,'success');break;
}});
