function applyMetadata(meta){state.config=meta.config;state.modelCatalog=meta.models||{};state.routingPresets=meta.routing_presets||{};state.history=meta.history||[];$('version').textContent='TradingAgents v'+meta.version;$('trade-date').value=meta.today;$('trade-date').max=meta.today;$('bt-end').value=meta.today;$('bt-end').max=meta.today;$('bt-start').max=meta.today;$('providers').replaceChildren();for(const provider of meta.providers)$('providers').append(new Option(provider,provider));updateConfigUI();renderWorkflow();renderHistory();}
async function init(){renderWorkflow();const cached=await api('bootstrap').catch(()=>null);if(cached){applyMetadata(cached);$('top-status').textContent='Đang đồng bộ bộ dữ liệu · đang xem cấu hình lần mở trước';$('health-label').textContent='Đang khởi động';}const meta=await api('meta');applyMetadata(meta);await refreshHistory();if(state.history[0])await openReport(state.history[0].id,false);const active=await api('status');if(active){state.started=active.started;setBusy(true,active.action);}else setBusy(false);$('health-label').textContent='Đã nạp cấu hình';$('health-dot').className='status-dot ready';}
