function metricValue(m){if(m.status==='not_applicable')return 'Không áp dụng cho ngân hàng';if(m.value===null)return 'Không có dữ liệu';if(m.unit.startsWith('fraction'))return formatNumber(m.value*100)+' %'+(m.unit.endsWith('/year')?'/năm':m.unit.endsWith('/day')?'/phiên':'');const units={'VND/share':'VND/cp','shares':'cp','shares/day':'cp/phiên','VND/day':'VND/phiên','ratio':'lần','index':'điểm','persons':'người','records':'dòng','percent':'%','VND at 2010 prices':'VND (giá năm 2010)'};return formatNumber(m.value)+' '+(units[m.unit]||m.unit);}
function formatNumber(value){return value===null||value===undefined?'Không có dữ liệu':new Intl.NumberFormat('vi-VN',{maximumFractionDigits:5}).format(value);}
function stat(container,label,value){const box=node('div','stat');box.append(node('span','',label),node('strong','',value));container.append(box);}
function renderEvidence(){const data=state.report?.integration||{};const q=data.quantitative;$('usage-details').replaceChildren();$('usage-summary').textContent='Báo cáo này chưa lưu bộ đếm usage.';const summary=$('evidence-summary');summary.replaceChildren();const body=$('evidence-body');body.replaceChildren();$('evidence-notes').replaceChildren();$('decision-card').replaceChildren(node('h2','','Quyết định danh mục'));if(!q){$('evidence-date').textContent='Báo cáo chưa có dữ liệu kiểm chứng';$('decision-card').append(node('p','help','Chọn hoặc chạy báo cáo mới có tích hợp dữ liệu Việt Nam.'));return;}stat(summary,'Mã / tiền tệ',q.ticker+' · VND');stat(summary,'Chỉ tiêu có số liệu',Object.values(q.metrics).filter(m=>m.value!==null).length+' / '+Object.values(q.metrics).filter(m=>m.status!=='not_applicable').length+' · '+Object.values(q.metrics).filter(m=>m.status==='not_applicable').length+' không áp dụng');stat(summary,'Giá phiên đã đóng',q.quote_date);$('evidence-date').textContent=q.quote_date;for(const [key,m]of Object.entries(q.metrics)){const tr=node('tr');tr.append(node('td','',metricLabels[key]||key),node('td',m.value===null||m.status==='stale'?'mono warning-text':'mono',metricValue(m)+(m.status==='stale'?' · Nguồn chậm':'')),node('td','',m.asof.replace(' public:',' · công bố ')+(m.published?' · công bố '+new Date(m.published).toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'')),node('td','',m.formula+' · '+m.source));body.append(tr);}const account=data.account_metrics;if(account?.status==='available'){for(const [key,m]of Object.entries(account.metrics)){const tr=node('tr');const labels={current_ticker_exposure:'Giá trị vị thế hiện tại',current_ticker_weight:'Tỷ trọng mã hiện tại',current_ticker_historical_var95_vnd:'VaR vị thế quy VND (lịch sử)',current_ticker_historical_cvar95_vnd:'CVaR vị thế quy VND (lịch sử)',remaining_position_budget:'Ngân sách vị thế còn lại',max_buy_quantity_at_reference:'Lô mua tối đa theo giá tham chiếu (không phải khuyến nghị)',settled_sell_quantity:'Cổ phiếu đã về, chưa bị giữ chỗ'};tr.append(node('td','',labels[key]||key),node('td','mono',metricValue(m)),node('td','',m.quote_date),node('td','',m.formula+' · Tài khoản tiền ảo'));body.append(tr);}}for(const line of [...(q.warnings||[]),...(q.basis||[])])$('evidence-notes').append(node('p','help',line));$('evidence-notes').append(node('p','help','Đây là độ phủ của bộ chỉ tiêu đang tính, không phải chứng nhận đầy đủ mọi nguồn. Giao dịch cổ đông lấy từ nguồn tổng hợp CafeF, chưa đối chiếu từng công bố với sở giao dịch; báo cáo cũ có thể chưa có dữ liệu này. F247 RSS cung cấp mẫu thảo luận công khai theo tag, không đại diện tâm lý toàn thị trường; báo cáo cũ có thể chưa lưu nguồn này. Vĩ mô NSDP/NSO có kỳ số liệu và độ trễ riêng; không dùng số tháng, số quý và số bình quân năm thay thế cho nhau. Xem cảnh báo và nguồn của lượt đã chọn.'));renderNewsCoverage(q.news_coverage);renderMarketNews(q.market_news);renderSourceEvidence(q.sources);renderQuoteEvidence(q.valuation_reconciliation);renderBankEvidence(q.bank_reconciliation);renderInsiderEvidence(q.insider_dealings);renderSocialEvidence(q.domestic_social);const handoffs=Object.values(data.handoffs||{});if(handoffs.length){$('evidence-notes').append(node('h3','','Chuyển giao dữ liệu giữa các vai trò'));for(const receipt of handoffs)$('evidence-notes').append(node('p','help',receipt.role+' · '+receipt.metric_count+' chỉ tiêu đã cung cấp, '+receipt.available_metrics+' có số liệu · snapshot '+receipt.snapshot_fingerprint.slice(0,12)+'…'));$('evidence-notes').append(node('p','help','Biên nhận xác minh đầu vào đã cung cấp; không chứng nhận mọi nhận định đầu ra đều đúng.'));}for(const [kind,checks]of Object.entries(q.financial_reconciliation||{}))for(const [field,proof]of Object.entries(checks))$('evidence-notes').append(node('p','help','Đối soát '+kind+'/'+field+': '+proof.basis+' · '+proof.checks.map(c=>c.year+' ('+c.basis+')').join(', ')));const grounding=data.grounding?.['Sentiment Analyst'];$('evidence-notes').append(node('p',grounding?.validated?'help':'warning-text',grounding?.validated?'Context Antigravity đã kiểm tra: '+grounding.readback.news_count+' tiêu đề, mã/ngày/snapshot và ID nguồn khớp. Kiểm tra này không chứng minh mọi suy luận đều đúng.':'Báo cáo này chưa có biên nhận kiểm tra context Antigravity.'));const quality=data.report_quality;if(quality?.execution_blocking_roles?.length)$('decision-card').append(node('p','warning-text','Chưa đủ lập luận để tạo lệnh: '+quality.execution_blocking_roles.join(', ')+'. Các vai trò bị giới hạn output cần hoàn tất và được đánh giá lại.'));const d=data.decision;if(d){$('decision-card').append(node('span','badge',d.rating),node('p','',d.executive_summary),node('p','help',d.execution.rationale),node('p','help',d.execution.action==='Hold'?'Hành động: Giữ nguyên tài khoản · Không tạo lệnh':'Đề xuất: '+d.execution.action+' · '+d.execution.quantity+' cp · '+formatNumber(d.execution.limit_price)+' VND/cp'));}else $('decision-card').append(node('p','help','Chưa có decision cấu trúc hợp lệ để tạo lệnh.'));if(d?.execution.data_gaps?.length)$('decision-card').append(node('p','warning-text','Cần xác minh: '+d.execution.data_gaps.join('; ')));const proposal=data.paper_proposal;if(proposal)$('decision-card').append(node('p','help','Tiền ảo: '+proposal.status+' · '+(proposal.reason||'Xem và duyệt ở Danh mục tiền ảo.')));const u=data.usage||{};$('usage-summary').textContent=!Array.isArray(u.items)?'Báo cáo này chưa lưu biên nhận usage; không suy ra request hoặc token bằng 0.':'Input đã báo: '+formatNumber(u.reported_input_tokens)+' token · Output đã báo: '+formatNumber(u.reported_output_tokens)+' token · '+(u.unreported_requests??'chưa rõ số')+' request chưa có bộ đếm. Input đọc từ cache provider (nếu có báo): '+formatNumber(u.reported_cached_input_tokens)+'. Token được báo không phải phần trăm hạn mức gói.';const table=node('table');const head=node('tr');for(const title of ['Vai trò','Lượt gọi backend','Cache hit'])head.append(node('th','',title));table.append(head);for(const [role,r]of Object.entries(u.roles||{})){const tr=node('tr');tr.append(node('td','',role),node('td','mono',r.calls),node('td','mono',r.cache_hits));table.append(tr);}renderProviderUsage(u,table);}
async function refreshPaper(){return window.PaperMarket?.refresh();}
$('paper-refresh').onclick=guard(refreshPaper);

function sourceTime(value){
 if(!value||value==='unavailable')return null;
 if(/^\d{4}-\d{2}-\d{2}$/.test(String(value)))return String(value).split('-').reverse().join('/');
 const parsed=new Date(value);
 return Number.isNaN(parsed.getTime())?String(value):parsed.toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});
}

function renderSourceEvidence(sources){
 const host=$('evidence-notes');
 const list=node('details');list.append(node('summary','','Nguồn dữ liệu · '+(sources||[]).length+' biên nhận'));
 list.append(node('p','help','Ngày truy xuất/quan sát là lúc ghi nhận nguồn, khác với kỳ số liệu và ngày công bố trong bảng phía trên.'));
 for(const source of sources||[]){
  const item=node('section');
  const names={prices:'Giá và khối lượng · Vietcap',news:'Tin doanh nghiệp · Vietcap',benchmark:'Chỉ số VNINDEX · Vietcap',fields:'Danh mục chỉ tiêu BCTC · Vietcap',income:'Báo cáo kết quả kinh doanh · Vietcap',balance:'Bảng cân đối kế toán · Vietcap',cash:'Báo cáo lưu chuyển tiền tệ · Vietcap',valuation:'Thống kê tỷ số tài chính · Vietcap',company_details:'Hồ sơ doanh nghiệp · Vietcap','VSDC registered-share history':'Lịch sử đăng ký cổ phiếu · VSDC','DIV published NHNN briefing':'Thông tin điều hành NHNN · DIV','Vietcombank reference FX':'Tỷ giá tham khảo · Vietcombank','CafeF shareholder dealings':'Giao dịch cổ đông/người nội bộ · CafeF','F247 public community RSS sample':'Mẫu thảo luận cộng đồng · F247 RSS'};
  const label=names[source.name]||source.name||'Nguồn chưa có tên';
  let url=null;try{const parsed=new URL(source.url||source.source_url);if(['https:','http:'].includes(parsed.protocol)&&!parsed.username&&!parsed.password)url=parsed.href;}catch{}
  const title=node(url?'a':'strong',url?'source-link':'',label);if(url)title.href=url;item.append(title);
  const retrieved=sourceTime(source.retrieved_at),observed=sourceTime(source.observed_at),published=sourceTime(source.published_at||source.published);
  if(retrieved)item.append(node('p','help','Truy xuất: '+retrieved));
  if(observed)item.append(node('p','help','Quan sát: '+observed));
  if(published)item.append(node('p','help','Công bố: '+published));
  if(!retrieved&&!observed)item.append(node('p','warning-text','Chưa lưu thời điểm truy xuất/quan sát.'));
  if(!url)item.append(node('p','help','Chưa có liên kết nguồn hợp lệ.'));
  list.append(item);
 }
 if(!(sources||[]).length)list.append(node('p','help','Báo cáo này chưa lưu biên nhận nguồn.'));
 host.append(list);
}

function renderNewsCoverage(data){
 const host=$('evidence-notes');host.append(node('h3','','Phạm vi tin doanh nghiệp'));
 if(!data){host.append(node('p','help','Báo cáo cũ chưa lưu cửa sổ và giới hạn bài; không suy ra đã lấy đủ tin.'));return;}
 const status={available:'Đã nhận mẫu tin',partial:'Mới nhận một phần; có lỗi nguồn',unavailable:'Nguồn không khả dụng',empty_sample:'Mẫu tin rỗng'};
 host.append(node('p',['partial','unavailable'].includes(data.status)?'warning-text':'help',(status[data.status]||'Chưa rõ trạng thái nguồn')+' · '+(data.start_date||'Chưa rõ ngày')+' → '+(data.end_date||'Chưa rõ ngày')));
 host.append(node('p','help','Giữ '+formatNumber(data.items_retained)+' bài · giới hạn '+formatNumber(data.article_limit)+' bài · nhận '+formatNumber(data.pages_received)+' trang.'));
 if(data.limit_reached)host.append(node('p','warning-text','Đã chạm giới hạn bài cấu hình; có thể còn tin chưa được đọc.'));
 host.append(node('p','help','Chỉ tiêu đề và tóm tắt từ nguồn tổng hợp; chưa đọc toàn văn. Mẫu rỗng không có nghĩa không có tin.'));
}

function renderMarketNews(data){
 if(!data)return;const host=$('evidence-notes');host.append(node('h3','','Tin tài chính & thị trường · VnEconomy RSS'));
 const records=data.records||[];
 host.append(node('p','help','Một nhà xuất bản, ba feed tài chính/chứng khoán/kinh tế thế giới. Mẫu tin thứ cấp, chưa đọc toàn văn; không thay cho số liệu chuẩn hoặc công cụ tin quốc tế của TradingAgents.'));
 host.append(node('p','help','Trạng thái: '+({available:'Đã nhận mẫu',partial:'Nguồn chưa đầy đủ',withheld:'Giữ lại do chưa đủ mốc thời gian',unavailable:'Nguồn không khả dụng',empty_sample:'Mẫu rỗng'}[data.status]||'Chưa rõ')+' · '+records.length+' bài đã cấp vào context · giới hạn '+formatNumber(data.article_limit)+' · nhìn lại '+formatNumber(data.look_back_days)+' ngày.'));
 if(data.omitted_count>0)host.append(node('p','help','Còn '+formatNumber(data.omitted_count)+' bài trong mẫu chưa đưa vào context theo giới hạn cấu hình.'));
 if(!records.length)host.append(node('p','warning-text','Chưa có mẫu đủ điều kiện trong snapshot này; có thể thiếu nguồn hoặc chưa có vintage đúng ngày, không có nghĩa thị trường không có tin.'));
 else{const details=node('details');details.append(node('summary','','Xem '+records.length+' tiêu đề và tóm tắt nguồn'));
  for(const row of records){const item=node('section');const link=node('a','source-link',row.title);link.href=row.url;item.append(link,node('p','help','VnEconomy · công bố '+(sourceTime(row.published)||'chưa rõ')+' · quan sát lần đầu '+(sourceTime(row.first_observed_at)||'chưa rõ')),node('p','',row.excerpt||'Nguồn không cung cấp tóm tắt.'),node('p','help',(row.excerpt_truncated?'Tóm tắt RSS đã giới hạn.':'Chỉ phần tóm tắt RSS.')));details.append(item);}host.append(details);}
 for(const warning of data.warnings||[])host.append(node('p','warning-text',warning));
}

function renderProviderUsage(usage,roleTable){
 const providers=new Map();
 for(const item of usage.items||[]){
  const provider=item.provider||'unknown';
  if(!providers.has(provider))providers.set(provider,{requests:0,input:0,output:0,inputKnown:0,outputKnown:0});
  const row=providers.get(provider);row.requests++;
  for(const [name,key]of [['input','input_tokens'],['output','output_tokens']])if(Number.isFinite(item.tokens?.[key])){row[name]+=item.tokens[key];row[name+'Known']++;}
 }
 const host=$('usage-details');host.replaceChildren();
 host.append(node('h3','','Lượt gọi thực tế theo nhà cung cấp'));
 if(!providers.size)host.append(node('p','help','Báo cáo này chưa lưu chi tiết provider; không thể xác nhận phân bổ từ cấu hình hiện tại.'));
 else{
  const table=node('table');const head=node('thead');const titles=node('tr');for(const title of ['Nhà cung cấp','Request đã lưu','Input token','Output token'])titles.append(node('th','',title));head.append(titles);table.append(head);const body=node('tbody');
  for(const [provider,row]of providers){const tr=node('tr');const token=name=>row[name+'Known']?formatNumber(row[name])+(row[name+'Known']<row.requests?' · một phần':''):'Chưa có bộ đếm';tr.append(node('td','',providerNames[provider]||provider),node('td','mono',row.requests),node('td','mono',token('input')),node('td','mono',token('output')));body.append(tr);}table.append(body);host.append(table);
 }
 host.append(node('p','help','Số request khác số vai trò: vòng công cụ, phản tư và lỗi có thể làm tăng lượt gọi. Bảng này tổng hợp biên nhận đã lưu, không tự cộng các lần thất bại thiếu biên nhận. Cache hit của ứng dụng không gọi backend. Token không phải chi phí hoặc phần trăm hạn mức gói.'));
 host.append(node('h3','','Chi tiết theo vai trò'),roleTable);
}

function renderInsiderEvidence(data){
 if(!data)return;
 const host=$('evidence-notes');host.append(node('h3','','Giao dịch cổ đông và người nội bộ'));
 host.append(node('p','help',(data.records?.length??0)+' dòng được lưu · trạng thái '+({available:'Có dữ liệu',partial:'Nguồn chưa đầy đủ',cached_source_error:'Dùng dữ liệu lưu — lỗi cập nhật',withheld:'Chưa đủ dữ liệu đúng thời điểm',unavailable:'Chưa lấy được nguồn'}[data.status]||data.status)+'. Ngày công bố ban đầu không chứng minh ngày thị trường biết kết quả. Đăng ký không phải thực hiện; ESOP không phải mua khớp lệnh. Nguồn không cung cấp giá thực hiện.'));
 if(!data.records?.length)return;
 const details=node('details');details.append(node('summary','','Xem toàn bộ '+data.records.length+' dòng nguồn đã lưu'));
 const table=node('table','insider-table');const head=node('tr');for(const title of ['Cá nhân / tổ chức','Vai trò','Phương thức / ghi chú','Công bố ban đầu','Kỳ đăng ký','Mua / bán đăng ký','Ngày kết thúc kết quả','Mua / bán báo cáo'])head.append(node('th','',title));table.append(head);
 const notesVi={"Before + reported buy - reported sell differs from after; corporate actions/other changes not reconciled": "Sở hữu trước + mua − bán chưa khớp sở hữu sau; chưa đối soát quyền và thay đổi khác.", "Reversed registration window retained as source error; no date repair; exclude from active-plan sizing": "Ngày bắt đầu đăng ký sau ngày kết thúc: giữ lỗi nguồn, không sửa ngày và không tính vào đăng ký còn hiệu lực.", "Source announcement date unknown": "Chưa xác định ngày công bố ban đầu.", "Dated result has missing buy/sell quantity; dated volume totals are incomplete": "Kết quả có ngày nhưng thiếu khối lượng mua/bán; chưa thể tính tổng đầy đủ.", "Source result date is after analysis cutoff; reported quantities are not counted in dated result subtotals": "Ngày kết quả sau thời điểm phân tích; không tính khối lượng này vào tổng kết quả.", "Reported real volume has no completed date; exclude from dated totals": "Có khối lượng báo cáo nhưng thiếu ngày hoàn tất; không đưa vào tổng theo kỳ.", "PublishedDate precedes completion; it cannot date publication of the completed result": "Ngày công bố nguồn sớm hơn ngày hoàn tất; không dùng nó làm ngày công bố kết quả."};
 const methods={esop:'ESOP',rights_or_corporate_action:'Quyền mua / sự kiện doanh nghiệp',explicit_exchange_matched:'Khớp lệnh theo ghi chú nguồn',gift_or_inheritance:'Tặng cho / thừa kế',negotiated:'Thỏa thuận',unspecified:'Chưa rõ'};
 for(const r of data.records){const tr=node('tr');for(const value of [r.party,r.role,(methods[r.mechanism]||r.mechanism)+' · '+(r.note||''),r.source_announcement_date||'Chưa rõ',(r.plan_begin||'?')+' → '+(r.plan_end||'?')+(r.plan_window_valid===false?' · Kỳ không hợp lệ':''),formatNumber(r.planned_buy)+' / '+formatNumber(r.planned_sell),r.reported_result_end||'Chưa rõ',formatNumber(r.reported_buy)+' / '+formatNumber(r.reported_sell)])tr.append(node('td','',value||'Chưa rõ'));table.append(tr);if(r.quality_notes?.length){const note=node('tr');const td=node('td','warning-text',r.quality_notes.map(n=>notesVi[n]||n).join('; '));td.colSpan=8;note.append(td);table.append(note);}}
 const wrap=node('div','table-wrap');wrap.append(table);details.append(wrap);host.append(details);
}

function renderSocialEvidence(data){
 if(!data)return;
 const host=$('evidence-notes');const rows=data.records||[];const selected=new Set((data.context_records||[]).map(r=>r.id));
 host.append(node('h3','','Thảo luận cộng đồng Việt Nam · F247 RSS'));
 const status={available:'Đã lấy mẫu',partial:'Nguồn chưa đầy đủ',cached_source_error:'Dùng dữ liệu lưu — lỗi cập nhật',withheld:'Chưa có phiên bản đúng thời điểm',unavailable:'Chưa lấy được nguồn'}[data.status]||data.status;
 host.append(node('p','help',status+' · '+rows.length+' chủ đề trong kỳ, '+selected.size+' chủ đề có nhắc mã được cấp vào context. Trích bài đầu; chưa đọc bình luận/hình ảnh. Tag có thể nói về doanh nghiệp khác. Nội dung là ý kiến chưa kiểm chứng, không phải dữ kiện tài chính hay khảo sát đại diện thị trường.'));
 if(data.retrieved_at)host.append(node('p','help','Nguồn được lấy: '+new Date(data.retrieved_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+'. Ngày RSS không chứng minh ngày sửa nội dung.'));
 if(!rows.length){host.append(node('p','warning-text','Chưa có mẫu thảo luận trong dữ liệu đã lưu; không đồng nghĩa không có thảo luận hoặc tâm lý trung lập.'));return;}
 const details=node('details');details.append(node('summary','','Xem '+rows.length+' chủ đề và trích đoạn đã lưu'));
 for(const r of rows){const item=node('section');const a=node('a','source-link',r.title);a.href=r.url;item.append(a,node('p','help',new Date(r.published).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' · '+(r.relevance==='tag_only_unverified'?'Chỉ gắn tag, trích đoạn chưa nhắc mã':r.relevance==='related_company_or_ambiguous'?'Đang nói về doanh nghiệp liên quan/khác mã; ngoài context trực tiếp':'Có nhắc mã trong tiêu đề/trích đoạn, chưa xác minh nội dung')+' · '+(selected.has(r.id)?'Đã cấp vào context':'Lưu để đối chiếu, ngoài mẫu context')),node('p','',r.excerpt),node('p','help',r.excerpt_truncated?'Trích đoạn đã cắt theo giới hạn nguồn; xem bài gốc để đọc tiếp.':'Phần mô tả RSS; không bao gồm toàn bộ chủ đề.'));details.append(item);}
 host.append(details);
}

function renderBankEvidence(proof){
 if(!proof)return;const host=$('evidence-notes');host.append(node('h3','','Đối soát chỉ tiêu ngân hàng'));
 host.append(node('p','help','Dư nợ/tiền gửi kế toán không phải LDR theo quy định NHNN. CIR TTM tự tính dùng quý liên tiếp đối chiếu với báo cáo năm. Các tỷ số nguồn NIM/CASA/nợ xấu được giữ riêng; chưa đối soát phương pháp và cửa sổ tính từ thuyết minh. Dấu âm của chi phí/dự phòng nguồn không có nghĩa chi phí kinh tế âm.'));
 host.append(node('p',proof.loan_net_reconciliation?.verified?'help':'warning-text',proof.loan_net_reconciliation?.verified?'Đã đối chiếu: dư nợ trước dự phòng + dự phòng có dấu = dư nợ sau dự phòng.':'Chưa đối chiếu được dự phòng với dư nợ gộp/thuần; không suy ra tỷ lệ dự phòng.'));
}

function renderQuoteEvidence(proof){
 const comparison=proof?.quote_comparison;if(!comparison)return;
 const host=$('evidence-notes');host.append(node('h3','','Đối chiếu giá dùng cho định giá'));
 host.append(node('p',proof.marketcap_price_aligned?'help':'warning-text','Giá đóng cửa chuẩn '+(comparison.canonical_date||'chưa rõ ngày')+': '+formatNumber(comparison.canonical_close)+' VND/cp. Giá hồ sơ nguồn: '+formatNumber(comparison.provider_price)+' VND/cp; vốn hóa/số cổ phiếu nguồn suy ra '+formatNumber(comparison.provider_implied_price)+' VND/cp.'));
 host.append(node('p','help','Hồ sơ được quan sát '+(comparison.provider_observed_at?new Date(comparison.provider_observed_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'chưa rõ')+'. Chưa có thời điểm cập nhật giá hồ sơ; ngày quan sát không phải ngày của mức giá.'));
 if(comparison.matching_prior_canonical_dates?.length)host.append(node('p','help','Giá suy ra trùng đóng cửa các phiên: '+comparison.matching_prior_canonical_dates.join(', ')+'. Trùng giá chưa chứng minh nguồn bị trễ hoặc có điều chỉnh.'));
 const shares=proof.registered_share_reconciliation;
 if(shares?.verified){host.append(node('p','help','Đã đối chiếu riêng '+formatNumber(shares.registered_shares)+' cổ phiếu đăng ký VSDC với số cổ phiếu hồ sơ hiện tại và vốn điều lệ kỳ '+shares.statement_period+'. Cổ phiếu quỹ/vốn ưu đãi được báo cáo bằng 0; không có thay đổi đăng ký sau kỳ báo cáo. Vốn hóa tính bằng giá đóng cửa chuẩn × cơ sở cổ phiếu đã đối chiếu. Chưa loại trừ mua lại chưa công bố sau kỳ báo cáo; số đăng ký tự nó không phải số lưu hành/free float.'));const a=node('a','source-link','Xem hồ sơ đăng ký VSDC');a.href=shares.source_url;host.append(a);}
 if(!proof.marketcap_price_aligned)host.append(node('p','warning-text',shares?.verified?'Giá/vốn hóa hồ sơ vẫn chưa khớp; không dùng P/E/P/B nguồn thay cho tỷ số tính riêng từ cơ sở cổ phiếu đã đối chiếu.':'Giá nguồn chưa khớp và chưa đủ đối chiếu cổ phiếu độc lập: giữ thiếu định giá liên quan.'));
}
